b_marital_status_determination = residual(source='s2', quote='determination of whether an individual is married shall be made as of the close of his taxable year')
b_spouse_death_determination = residual(source='s2', quote='if his spouse dies during his taxable year such determination shall be made as of the time of such death')
b_legally_separated_condition = residual(source='s3', quote='legally separated from his spouse under a decree of divorce or of separate maintenance')
@scope('s0') 
def marital_status_scope(): 
    return True
@scope('s1') 
def general_rule_scope(): 
    return marital_status_scope
@scope('s2') 
def marital_status_determination_scope(): 
    return general_rule_scope
@scope('s3') 
def legally_separated_scope(): 
    return general_rule_scope
@scope('s4') 
def married_individuals_living_apart_scope(): 
    return general_rule_scope
@scope('s5') 
def married_individuals_living_apart_condition_scope(): 
    return married_individuals_living_apart_scope
@rule('s2', otherwise=False) 
def marital_status_determination_rule(): 
    return (marital_status_determination_scope and (b_marital_status or b_spouse_death_determination or b_legally_separated_condition))
@rule('s3', otherwise=False) 
def legally_separated_rule(): 
    return (legally_separated_scope and b_legally_separated)
@rule('s6', otherwise=False) 
def home_principal_condition_rule(): 
    return (married_individuals_living_apart_condition_scope and b_home_principal_condition)
@rule('s7', otherwise=False) 
def cost_furnish_condition_rule(): 
    return (married_individuals_living_apart_condition_scope and b_cost_furnish_condition)
@rule('s8', otherwise=False) 
def spouse_not_home_during_period_condition_rule(): 
    return (married_individuals_living_apart_condition_scope and b_spouse_not_home_during_period_condition)
@rule('s9', otherwise=False) 
def married_individuals_living_apart_rule(): 
    return (married_individuals_living_apart_condition_scope and b_home_principal_condition and b_cost_furnish_condition and b_spouse_not_home_during_period_condition)
